game.herramientas.define('suelo_flotante', {
  // ── QUÉ SE LLEVA EN LA MANO ────────────────────────────────────────────────────────────────────
  // Cualquier clave del catálogo: un habitante (`hab:...`) o un asset (`asset:assets/x.vox.json`).
  dibujo: 'hab:caballito-de-mar-hd',
  nombre: 'suelo flotante',
  mira: '⊙',                       // el punto de mira mientras esté puesta
  ayuda: 'suelo_flotante · clic izq: romper bloque · clic dcho: baldosa bajo pies',

  // ── POSTURA EN LA MANO ─────────────────────────────────────────────────────────────────────────
  // Lo que no se ponga aquí cae en los mandos globales de siempre (`game.showTool.pos/rot/scale`).
  pos: [0.85, -0.55, 0],
  rot: [-6, -80, -18],
  escala: 0.75,
  alcance: 4,                      // hasta dónde llega el foto (bloques); sin esto, el alcance normal

  // ── EL GESTO DEL CLIC ──────────────────────────────────────────────────────────────────────────
  // Misma máquina de 3 fases del pico (impulso → disparo → vuelta); lo que no se toque hereda del pico.
  // Una suelo_flotante es más rápida y más plana que un hachazo: casi no baja, pero llega más lejos y gira más.
  gesto: { dur: 0.50, windupP: 0.12, strikeP: 0.042, windupRot: -0.55, chopRot: 0.60, lift: 0.016, drop: 0.05, reach: -0.0155 },
  gestoBotones: [0, 2],            // se anima con los DOS botones (por defecto solo el izquierdo)

  // ── MOVIMIENTO PROPIO (opcional) ───────────────────────────────────────────────────────────────
  // Se llama en cada frame con lo ya calculado y devuelve desplazamientos que se SUMAN: eje de cámara
  // (x derecha, y arriba, z hacia ti) y grados. Aquí, un vaivén de reposo que se apaga durante el foto.
  anima(e){
    const quieta = (e.disparo < 0) ? 1 : 0;          // e.disparo = 0..1 mientras dura el gesto, -1 si está parada
    return {
      pos: [0, Math.sin(e.t * 1.4) * 0.012 * quieta, 0],
      rot: [0, 0, Math.sin(e.t * 0.9) * 2.5 * quieta]
    };
  },

  // ── LO QUE PASA AL HACER CLIC ──────────────────────────────────────────────────────────────────
  // `c` viene masticado: c.celda (bloque apuntado), c.clave (su material), c.delante (la celda de al
  // lado, donde se pondría algo), c.punto, c.dist, c.normal, c.pos/yaw/pitch, c.ranura, c.bloque.
  izquierdo(c){
    if(c && c.celda){
      const bx = c.celda[0], by = c.celda[1], bz = c.celda[2];
      const before = mc.grid[mcIdx(bx, by, bz)];
      if(before){
        mcSetBlock(bx, by, bz, 0);
        mcPushHist({ t: 'b', x: bx, y: by, z: bz, before, after: 0 });
        mcRemeshAround(bx, bz);
        mcScheduleSave();
      }
    } else {
      mcBreak();
    }
  },

  derecho(c){
    const cx = Math.floor(mc.pos[0]);
    const cy = Math.floor(mc.pos[1]);
    const cz = Math.floor(mc.pos[2]);
    const targetY = cy - 1;

    // Toma el material de la ranura activa (o fallback a 'log' si la ranura está vacía)
    const matId = (mc.hotbar && mc.hotbar[mc.sel]) || mcResolveMat('log');
    if (!matId) return;

    const edits = [];
    for (let x = cx - 1; x <= cx + 1; x++){
      for (let z = cz - 1; z <= cz + 1; z++){
        if (!mcInside(x, targetY, z)) continue;
        const idx = mcIdx(x, targetY, z);
        const before = mc.grid[idx];
        if (before === matId) continue;

        mcSetBlock(x, targetY, z, matId);
        edits.push({ x, y: targetY, z, before, after: matId });
      }
    }

    if (!edits.length) return;

    mcPushHist({ t: 'bb', edits });
    mcRemeshEdiciones(edits);
    mcScheduleSave();
    mcUnstick();
  }
});

